                for (actor in result.analyzers) {
                    println("SOA_STATIC_TRACE run=$run actor=${actor.key} nonZeroInitial=${actor.nonZeroInitial}")
                }
                // These are observed onProcess premises, not a claim that released initial storage is retained.
                val observedInitials = seen.processed.filter { it.run == run }.flatMap { row ->
                    row.delta.premise.members.map { row.method to it.toPattern() }
                }.toSet()
                println("SOA_STATIC_TRACE run=$run observedProcessedPremises=$observedInitials")
            }
            for (run in 3..4) {
