                "run1ServiceAbsent=${row.run1ServiceAbsent}")
            for (row in seen.views) println("SOA_STATIC_TRACE appliedView run=${row.run} part=${row.part} view=${row.view}")
            for (row in seen.summaries) println("SOA_STATIC_TRACE appliedSummary run=${row.run} part=${row.part} " +
